import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../services/api';
import '../styles/Login.css';

function Login() {
  const [formData, setFormData] = useState({
    usernameOrEmail: '', // Cập nhật để hỗ trợ cả username và email
    password: ''
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value.trim() // Loại bỏ khoảng trắng thừa
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    // Validate cơ bản
    if (!formData.usernameOrEmail || !formData.password) {
      setError('Vui lòng nhập đầy đủ username/email và mật khẩu');
      return;
    }

    setIsLoading(true);

    try {
      // Thêm log debug
      console.log('Login request:', {
        usernameOrEmail: formData.usernameOrEmail,
        password: formData.password
      });

      // Gọi API login
      const response = await authAPI.login({
        usernameOrEmail: formData.usernameOrEmail,
        password: formData.password
      });

      console.log('Login response:', response);

      // Kiểm tra kết quả trả về
      if (!response?.data?.token) {
        throw new Error(response?.message || 'Không nhận được token từ server');
      }

      // Lưu token và chuyển hướng
      localStorage.setItem('token', response.data.token);
      localStorage.setItem('user', JSON.stringify(response.data.user));
      
      navigate('/', { replace: true });

    } catch (err) {
      console.error('Login error details:', {
        error: err,
        response: err.response
      });
      
      // Xử lý thông báo lỗi chi tiết
      let errorMessage = 'Đăng nhập thất bại';
      
      if (err.response) {
        // Lỗi từ phía server
        errorMessage = err.response.data?.message || 
                      err.response.statusText || 
                      `Lỗi server (${err.response.status})`;
      } else if (err.message) {
        // Lỗi từ phía client hoặc network
        errorMessage = err.message;
      }

      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-container">
      <h2>Đăng Nhập</h2>
      {error && (
        <div className="error-message">
          <i className="error-icon">⚠️</i> {error}
        </div>
      )}
      
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-group">
          <label htmlFor="usernameOrEmail">Username hoặc Email:</label>
          <input
            id="usernameOrEmail"
            type="text"
            name="usernameOrEmail"
            value={formData.usernameOrEmail}
            onChange={handleChange}
            required
            autoComplete="username"
            aria-describedby="emailHelp"
          />
          <small id="emailHelp" className="form-text">
            Nhập username hoặc email bạn đã đăng ký
          </small>
        </div>
        
        <div className="form-group">
          <label htmlFor="password">Mật khẩu:</label>
          <input
            id="password"
            type="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            required
            autoComplete="current-password"
            minLength="6"
          />
        </div>
        
        <div className="form-actions">
          <button 
            type="submit" 
            className="login-button"
            disabled={isLoading}
            aria-busy={isLoading}
          >
            {isLoading ? (
              <>
                <span className="spinner"></span> Đang đăng nhập...
              </>
            ) : 'Đăng Nhập'}
          </button>
          
          <div className="forgot-password">
            <a href="/forgot-password">Quên mật khẩu?</a>
          </div>
        </div>
      </form>
      
      <div className="register-prompt">
        <p>Chưa có tài khoản? <a href="/register">Đăng ký ngay</a></p>
      </div>
    </div>
  );
}

export default Login;
